/*
 * A037442  Positive numbers having the same set of digits in base 8 and base
 *          10.
 * https://oeis.org/A037442
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 7, u16 n <= 120, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by brute‑force search: a(n) is the n‑th positive
   integer whose set of decimal digits equals its set of octal digits. */

#include <stdint.h>

static inline uint32_t digit_mask_uint64(uint64_t val, unsigned base)
{
    uint32_t mask = 0;
    if (val == 0)
        return 1U << 0;
    while (val)
    {
        mask |= 1U << (val % base);
        val /= base;
    }
    return mask;
}

seq_t a(idx_t n)
{
    if (n == 0)
        return 0;          /* offset starts at 1 */
    idx_t count = 0;
    idx_t cand = 1;
    for (;; ++cand)
    {
        if (digit_mask_uint64((uint64_t)cand, 10) ==
            digit_mask_uint64((uint64_t)cand, 8))
        {
            ++count;
            if (count == n)
                return (seq_t)cand;
        }
    }
}
